// Presentation geometry aligned to the visible tray rim in the overhead video.
// These dimensions and the fabric's depth are estimates, not measured CAD.
// The same footprint drives both the tray walls and the cloth support surface.
// A submillimetre clearance prevents the source's coplanar base-plate faces
// from flickering through the continuous presentation surface.
const xdofSceneLayout={table:.756,worktop:{x:.45,y:0,depth:.9,width:1.3,top:.7508,thickness:.018,border:.016},tray:{x:.756,y:-.437,depth:.313,width:.27,angle:-.095,bottom:.764,rim:.875,wall:.006}};
// uynitsuj.github.io patch: bin moved 5 cm toward the table's right edge (y was -.387) and
// walls lowered 3.5 cm (rim was .91). The cloth pile and wall contact read these too.

function xdofCreateTraySupport({tray}=xdofSceneLayout) {
  const c=Math.cos(tray.angle),s=Math.sin(tray.angle);
  const halfX=tray.depth/2-tray.wall,halfY=tray.width/2-tray.wall;
  return function support(origin,ray) {
    // Intersect the camera ray with the tray's interior column. Keeping the
    // vertex on that ray preserves the original image registration exactly.
    const ox=c*(origin[0]-tray.x)+s*(origin[1]-tray.y);
    const oy=-s*(origin[0]-tray.x)+c*(origin[1]-tray.y);
    const dx=c*ray.x+s*ray.y,dy=-s*ray.x+c*ray.y;
    let enter=0,exit=Infinity;
    if(Math.abs(dx)<1e-9){if(Math.abs(ox)>halfX)return null}
    else{const a=(-halfX-ox)/dx,b=(halfX-ox)/dx;enter=Math.max(enter,Math.min(a,b));exit=Math.min(exit,Math.max(a,b))}
    if(Math.abs(dy)<1e-9){if(Math.abs(oy)>halfY)return null}
    else{const a=(-halfY-oy)/dy,b=(halfY-oy)/dy;enter=Math.max(enter,Math.min(a,b));exit=Math.min(exit,Math.max(a,b))}
    if(exit<=enter||ray.z>=0)return null;
    const low=Math.max(tray.bottom+.003,origin[2]+ray.z*exit+.001);
    const high=Math.min(tray.rim+.05,origin[2]+ray.z*enter-.001);
    if(low>high)return null;
    // A restrained, smooth pile inside the tray, replacing the flat tabletop
    // projection. Its folds and boundary still come from the recorded pixels.
    let height=tray.bottom+.09;
    for(let i=0;i<2;i++) {
      const t=(height-origin[2])/ray.z;
      const x=(ox+dx*t)/halfX,y=(oy+dy*t)/halfY;
      const mound=Math.max(0,1-.65*x*x-.65*y*y);
      height=Math.max(low,Math.min(high,tray.bottom+.055+.08*mound));
    }
    return height;
  };
}




// A view-dependent surface made from the recorded overhead image. This is
