  const entry=xdofRecordingSequences.get(frame);
  if(!entry)return [frame];
  return Array.from({length:radius*2+1},(_,offset)=>entry.frames[Math.max(0,Math.min(entry.frames.length-1,entry.index+offset-radius))]);
