  const size=128,grain=new Uint8Array(size*size*4);
  for(let i=0;i<size*size;i++) {
    const value=218+Math.round((random()+random()-1)*22);
    grain[i*4]=grain[i*4+1]=grain[i*4+2]=value;grain[i*4+3]=255;
  }
